import { Input } from '@/components/ui/input';

interface Props {
    label?: string;
    placeholder?: string;
    value: string;
    onValueChange: (value: string) => void;
    reasons: string[];
    onAddReason: () => void;
    onRemoveReason: (index: number) => void;
}

export default function MultipleReasonsInput({
    label,
    placeholder,
    value,
    onValueChange,
    reasons,
    onAddReason,
    onRemoveReason,
}: Props) {
    return (
        <div className="col-span-1 sm:col-span-2 w-full">
            <label className="text-primery-blue-900 font-medium text-[18px] leading-[33.73px] tracking-normal text-start">
                {label}
            </label>
            <div className="mt-1 flex items-center gap-2">
                <Input
                    value={value}
                    onChange={(e) => onValueChange(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter') {
                            e.preventDefault();
                            onAddReason();
                        }
                    }}
                    placeholder={placeholder}
                    className="h-10"
                />
                <button
                    type="button"
                    onClick={onAddReason}
                    className="h-10 w-10 rounded-md border border-primery-blue-200 text-primery-blue-600 hover:bg-primery-blue-50 text-xl leading-none"
                    aria-label="إضافة سبب"
                >
                    +
                </button>
            </div>
            {reasons.length > 0 && (
                <div className="mt-3 flex flex-wrap gap-2">
                    {reasons.map((reason, index) => (
                        <span
                            key={`${reason}-${index}`}
                            className="inline-flex items-center gap-2 rounded-full bg-primery-blue-50 border border-primery-blue-100 px-3 py-1 text-sm text-primery-blue-700"
                        >
                            {reason}
                            <button
                                type="button"
                                onClick={() => onRemoveReason(index)}
                                className="text-primery-blue-500 hover:text-primery-blue-700"
                                aria-label="حذف السبب"
                            >
                                ×
                            </button>
                        </span>
                    ))}
                </div>
            )}
        </div>
    );
}
